mapper.select:
WITH customer_base AS ( SELECT pc.id AS customer_id, '01' AS customer_type_code, pc.name AS customer_name, pc.gender, pc.birth_date FROM potential_customer pc WHERE pc.conversion_status_code = '01' AND pc.sales_user_id = #{salesUserId}
UNION ALL
SELECT ic.integrated_customer_id AS customer_id, '02' AS customer_type_code, ic.name AS customer_name, ic.gender, ic.birth_date FROM integrated_customer ic WHERE ic.sales_user_id = #{salesUserId} ) SELECT COUNT(*) FROM customer_base cb WHERE 1 = 1
AND cb.customer_name LIKE CONCAT('%', #{customerName}, '%')
AND TIMESTAMPDIFF(YEAR, cb.birth_date, CURDATE()) = #{age}
AND cb.gender = #{gender}
AND ( SELECT c.contract_status_code FROM contract c WHERE c.insured_id = cb.customer_id ORDER BY CASE c.contract_result_status_code WHEN '01' THEN 1 WHEN '02' THEN 2 WHEN '03' THEN 3 ELSE 9 END, c.updated_at DESC, c.id DESC LIMIT 1 ) IN
#{code}
AND EXISTS ( SELECT 1 FROM customer_report cr WHERE cr.conversion_status_code = cb.customer_type_code AND cr.customer_id = cb.customer_id )
AND NOT EXISTS ( SELECT 1 FROM customer_report cr WHERE cr.conversion_status_code = cb.customer_type_code AND cr.customer_id = cb.customer_id )
AND EXISTS ( SELECT 1 FROM daily_action_item dai WHERE dai.conversion_status_code = cb.customer_type_code AND dai.customer_id = cb.customer_id AND dai.is_completed = FALSE AND dai.trigger_type_code IN ('06', '07', '08') )
AND NOT EXISTS ( SELECT 1 FROM daily_action_item dai WHERE dai.conversion_status_code = cb.customer_type_code AND dai.customer_id = cb.customer_id AND dai.is_completed = FALSE AND dai.trigger_type_code IN ('06', '07', '08') )
